    if (!m) { m = ar ? /خلال (\d+ (?:أيام عمل|أيام|يوم|أسابيع)|أسبوع|أسبوعين|شهر)(?=[ .،:]|$)/.exec(t) : /[Ww]ithin (\d+ (?:working )?(?:days?|weeks?))/.exec(t); if (!m) return ''; }
