      if (parts.length < 2) { var m = /^(.*\S)\s+([\d٠-٩۰-۹][\d٠-٩۰-۹.,٫٬]*)\s*(?:ر\.?س|ريال|SAR)?$/i.exec(line); if (m) parts = [m[1], m[2]]; else { var only = JT.parse(line.replace(/ر\.?س|ريال|SAR/gi, '')); if (only > 0) parts = ['', line]; } }
