      el.appendChild(JT.nextStep({ title: T('vat.nextT'), text: T('vat.nextP'), btn: T('vat.nextBtn'), svc: 'review', href: JT.prod('review'), wa: T('vat.nextWa') }));
      var mbar = JT.mobileBar(T('vat.bigL'));

